    /*Definition Start*/
    let obsRepair: Repair = l({
      logic: () =>
        getRepository(Repair).find(
          (o: any) =>
            l({
              logic: () => o.Id === id,
              description: "o.Id=id",
            }).build().pass,
        ),
      description: "Repair.allInstance()->any(o|o.Id=id)",
    }).build().pass;
    let obsStaff: Staff = l({
      logic: () =>
        getRepository(Staff).find(
          (o: any) =>
            l({
              logic: () => o.Id === sid,
              description: "o.Id=sid",
            }).build().pass,
        ),
      description: "Staff.allInstance()->any(o|o.Id=sid)",
    }).build().pass;
    let obsDevice: Device = l({
      logic: () =>
        getRepository(Device).find(
          (o: any) =>
            l({
              logic: () => o.Id === did,
              description: "o.Id=did",
            }).build().pass,
        ),
      description: "Device.allInstance()->any(o|o.Id=did)",
    }).build().pass;
    /*Definition End*/

    /*Precondition Start*/
