        .and({
          logic: () => getRepository(Device).includes(obsDevice),
          description: "Device.allInstance()->includes(obsDevice)",
        })
        .and({
          logic: () => obsDevice.Contacts.includes(obsStaff),
          description: "obsDevice.Contacts->includes(obsStaff)",
        })
        .and({
          logic: () => obsStaff.Role === 3,
          description: "obsStaff.Role=3",
        })
        .and({
          logic: () => obsRepair.RelatedDevice === obsDevice,
          description: "obsRepair.RelatedDevice=obsDevice",
        })
        .and({
          logic: () => obsRepair.Id === id,
          description: "obsRepair.Id=id",
        })
        .and({
          logic: () => obsStaff.Id === sid,
          description: "obsStaff.Id=sid",
